const CHARACTER_OPTIONS={body:['boy','girl'],outfit:['green','red','blue'],gear:['compass','book','map']};
const GEAR_NAMES={compass:'Компас',book:'Блокнот',map:'Карта'};
const OUTFIT_NAMES={green:'Лесной',red:'Ягодный',blue:'Небесный'};
function characterData(u){const c=u?.character||u||{};return {body:CHARACTER_OPTIONS.body.includes(c.body)?c.body:'boy',outfit:CHARACTER_OPTIONS.outfit.includes(c.outfit)?c.outfit:'green',gear:CHARACTER_OPTIONS.gear.includes(c.gear)?c.gear:'compass',path:['trail','story','music'].includes(c.path)?c.path:'trail',backpack:c.backpack!==false,companion:c.companion==='none'?'none':'lynx'}}
function gameCharacter(u,options={}){const c=characterData(u),x={green:'0%',red:'50%',blue:'100%'}[c.outfit],y=c.body==='girl'?'100%':'0%';return `<span class="game-character ${options.className||''}"><span class="character-sprite" style="--sprite-x:${x};--sprite-y:${y}" role="img" aria-label="${c.body==='girl'?'Девочка':'Мальчик'}-путешественник, ${OUTFIT_NAMES[c.outfit].toLowerCase()} цвет одежды"></span>${u?.equippedHat==='burek'?'<span class="character-hat">'+storyRewardIcon('burek')+'</span>':''}</span>`}
function readSession(key){try{return JSON.parse(sessionStorage.getItem(key))}catch{return null}}
function setSession(key,value){try{sessionStorage.setItem(key,JSON.stringify(value))}catch{}}
let pendingJoin=readSession('ethnohod-pending-join');
let creatorState=null;
function gameHomePage(u){const ready=!!u?.character;return `<div class="game-world"><section class="welcome-game"><div class="welcome-copy"><h1>${ready?'Новые открытия уже ждут тебя!':'Твоё большое приключение начинается здесь!'}</h1><p>${ready?`${esc(u.nick)}, выбирай маршрут, знакомься с культурой народов России и пополняй коллекцию открытий.`:'Создай своего путешественника и отправляйся исследовать Россию. Впереди — удивительные истории, задания и награды!'}</p><div class="welcome-actions"><a class="kid-primary" href="#${ready?'map':u?'character':'login'}">${ready?'Продолжить путешествие':'Создать персонажа'} ${kidIcon(ready?'arrow':'spark')}</a>${!u?'<a class="game-text-link" href="#login/return">У меня уже есть персонаж →</a>':'<a class="btn secondary" href="#profile">Мой дневник</a>'}</div><div class="welcome-features"><span>${kidIcon('compass')} Исследуй регионы</span><span>${kidIcon('book')} Узнавай новое</span><span>${kidIcon('star')} Собирай значки</span></div></div><div class="welcome-art"><img class="welcome-scenery" src="assets/ural-postcard.jpg" alt="Иллюстрированная долина с рекой и зелёными горами" width="700" height="390"><div class="welcome-art-cloud">${kidIcon('flag')} Готов к открытиям?</div><div class="welcome-hero-boy">${gameCharacter({body:'boy',outfit:'green',gear:'compass'},{gear:false})}</div><div class="welcome-hero-girl">${gameCharacter({body:'girl',outfit:'red',gear:'book'},{gear:false})}</div><div class="welcome-lynx">${visitCompanionMarkup()}</div><div class="welcome-art-ground"></div></div></section><section class="welcome-how"><h2>Собери свою историю</h2><div class="grid"><article class="game-panel"><span class="welcome-step">1</span><h3>Создай героя</h3><p>Выбери персонажа, одежду и снаряжение. Придумай ник — и можно в путь!</p></article><article class="game-panel"><span class="welcome-step">2</span><h3>Выбери экспедицию</h3><p>На карте тебя ждёт Башкортостан. Данияр зовёт помочь семье подготовиться к Сабантую.</p></article><article class="game-panel"><span class="welcome-step">3</span><h3>Забирай открытия</h3><p>Готовь угощения, украшай наряды и разговаривай с семьёй. Сохраняй рецепты и подарки.</p></article></div></section><section class="welcome-teacher game-panel"><div><h2>Путешествуйте с группой</h2><p>Создайте туристическую группу и передайте участникам код маршрута.</p></div><a class="btn secondary" href="#organizer">Кабинет организатора ${kidIcon('arrow')}</a></section></div>`}
function onboardingSteps(active){return `<ol class="onboard-steps" aria-label="Создание путешественника"><li class="${active===1?'active':'done'}"><span>${active>1?kidIcon('check'):'1'}</span>${pendingJoin?.mode==='solo'?'Самостоятельно':'Код группы'}</li><li class="${active===2?'active':''}"><span>2</span>Твой персонаж</li><li><span>3</span>Приключение</li></ol>`}
function renderGameLogin(returning=false){layout(returning?'С возвращением!':'Начнём с кода группы',`<div class="game-world">${onboardingSteps(1)}<div class="join-layout"><section class="join-story"><img src="assets/lynx-guide.png" alt="Рысёнок Тим — твой проводник" width="230" height="280"><div class="game-panel"><h2>${returning?'Тим уже соскучился!':'Привет! Я Тим.'}</h2><p>${returning?'Введи код и свой ник. Продолжим с того места, где остановились.':'Организатор даст тебе код группы. Введи его, а затем соберём твоего персонажа — совсем как в игре!'}</p></div></section><section class="join-card game-panel"><form id="join"><label for="classCode">Код группы</label><input id="classCode" name="code" autocomplete="off" autocapitalize="characters" spellcheck="false" placeholder="Например, ETNO5" maxlength="20" required>${returning?'<label for="returnNick">Твой ник</label><input id="returnNick" name="nick" autocomplete="nickname" placeholder="Ник твоего персонажа" minlength="2" maxlength="20" required>':'<p>Код помогает найти твою группу. Если ты просто знакомишься с Этноходом, попробуй демо.</p>'}<p class="error" id="err" role="alert"></p><button type="submit" class="kid-primary">${returning?'Продолжить путешествие':'Создать персонажа'} ${kidIcon('arrow')}</button></form>${returning?'<a class="game-text-link" href="#login">Хочу создать нового персонажа →</a>':'<button type="button" class="btn secondary" id="demoCode">Попробовать демо</button><a class="game-text-link" href="#login/return">У меня уже есть персонаж →</a>'}<p class="join-storage-note">Персонаж и прогресс сохраняются в этом браузере.</p></section></div></div>`);if($('#demoCode'))$('#demoCode').onclick=()=>{$('#classCode').value='ETNO5';$('#classCode').focus()};$('#join').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),code=String(f.get('code')||'').trim().toUpperCase(),nick=String(f.get('nick')||'').trim();if(!db.classes.some(c=>c.code===code)){$('#err').textContent='Группа не найдена. Проверь код у организатора или попробуй демо.';return}if(returning){const found=db.users.find(v=>v.code===code&&v.nick===nick);if(!found){$('#err').textContent='Персонаж с таким ником не найден в этой группе. Проверь ник или создай нового героя.';return}db.current=found.id;save();pendingJoin=null;creatorState=null;sessionStorage.removeItem('ethnohod-pending-join');sessionStorage.removeItem('ethnohod-character-draft');location.hash=found.character?'map':'character';return}pendingJoin={code,nonce:Date.now()};creatorState=null;setSession('ethnohod-pending-join',pendingJoin);sessionStorage.removeItem('ethnohod-character-draft');location.hash='character'}}
function renderCharacterStudio(){
const existing=user(),creating=!!pendingJoin;if(!creating&&!existing){location.hash='login';return}
const context=creating?'new:'+pendingJoin.nonce:'edit:'+existing.id;
if(!creatorState||creatorState.context!==context){const cached=readSession('ethnohod-character-draft');creatorState=cached?.context===context?cached:{context,...characterData(creating?{}:existing),nick:creating?'':existing.nick,tab:'body',mirrored:false}}
creatorState.path=['trail','story','music'].includes(creatorState.path)?creatorState.path:'trail';creatorState.backpack=creatorState.backpack!==false;creatorState.companion=creatorState.companion==='none'?'none':'lynx';
const paths=[{id:'trail',name:'Следопыт',text:'Карты, тропинки и новые места',icon:'compass',stats:[85,60,45]},{id:'story',name:'Сказитель',text:'Легенды и истории народов',icon:'book',stats:[70,40,85]},{id:'music',name:'Музыкант',text:'Мелодии, ритмы и звуки',icon:'star',stats:[55,50,95]}];
if(!['body','outfit'].includes(creatorState.tab))creatorState.tab='body';
const tabs=[['body','Герой','spark'],['outfit','Одежда','bag']];
layout(creating?'Создай своего героя':'Твой герой, твои правила',`<div class="hero-studio">${creating?onboardingSteps(2):''}<div class="hero-studio-grid"><section class="hero-studio-options game-panel"><h2>Твой образ</h2><div class="hero-studio-tabs" role="group" aria-label="Настройки героя">${tabs.map(([id,label,icon])=>`<button type="button" data-hero-tab="${id}" aria-pressed="${(creatorState.tab||'body')===id}">${kidIcon(icon)}<span>${label}</span></button>`).join('')}</div><div id="heroOptions"></div></section><section class="hero-studio-preview game-panel"><div class="hero-studio-stage"><div id="heroModel">${gameCharacter({...(creating?{}:existing),character:creatorState},{gear:false})}</div></div><div class="hero-studio-tools"><button type="button" class="btn secondary" id="heroRandom">${kidIcon('spark')} Случайный герой</button></div><label for="characterNick">Как зовут твоего героя?</label><input id="characterNick" class="character-name-input" name="nick" form="characterForm" value="${esc(creatorState.nick)}" placeholder="Придумай ник" autocomplete="nickname" minlength="2" maxlength="20" required><p class="hero-studio-hint">Вымышленный ник, от 2 до 20 символов</p><p id="heroSummary" aria-live="polite"></p></section><section class="hero-studio-path game-panel"><h2>Что тебе интересно?</h2><div class="hero-studio-paths">${paths.map(p=>`<button type="button" data-hero-path="${p.id}" aria-pressed="${creatorState.path===p.id}"><span class="hero-path-icon">${kidIcon(p.icon)}</span><span><strong>${p.name}</strong><small>${p.text}</small></span><span class="hero-path-check" aria-hidden="true">✓</span></button>`).join('')}</div><div id="heroStats"></div><p class="hero-studio-hint">Это настроение героя, а не оценка тебя. Все приключения доступны каждому.</p><form id="characterForm"><p id="characterError" class="error" role="alert"></p><button type="submit" class="kid-primary">${creating?'Отправиться в путь':'Сохранить героя'}</button></form><a class="game-text-link" href="#${creating?'login':'profile'}">${creating?'Изменить способ входа':'Вернуться в дневник'}</a></section></div><dialog id="heroCreated" class="hero-created" aria-labelledby="heroCreatedTitle"><div class="hero-created-scene"><div class="hero-created-art" id="heroCreatedArt"></div><img class="hero-created-helper" src="assets/marten-helper.png" width="100" height="112" alt="Куница — твой спутник в путешествии"></div><h2 id="heroCreatedTitle">${creating?'Твой герой готов!':'Новый образ сохранён!'}</h2><h3 id="heroCreatedName"></h3><p id="heroCreatedPath"></p><p>${creating?'Впереди — новые места и открытия. Открой карту и выбери локацию для первого путешествия. Куница поможет в пути!':'Твои открытия и подарки остались с тобой. Можно продолжать путешествие!'}</p><button type="button" class="kid-primary" id="heroContinue">${creating?'Открыть карту':'Вернуться в дневник'}</button></dialog></div>`);
const root=document.querySelector('.hero-studio');
const saveDraft=()=>setSession('ethnohod-character-draft',creatorState);
function option(part,value,label,art=''){return `<button type="button" class="hero-option ${creatorState[part]===value?'selected':''}" data-hero-part="${part}" data-hero-value="${String(value)}" aria-pressed="${creatorState[part]===value}">${art}<span>${label}</span><i aria-hidden="true">✓</i></button>`}
function options(){const tab=creatorState.tab||'body';root.querySelectorAll('[data-hero-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.heroTab===tab)));let content='';
if(tab==='body')content=`<h3>Кто отправится в путь?</h3><div class="hero-option-grid hero-body-grid">${[['boy','Мальчик'],['girl','Девочка']].map(([v,l])=>option('body',v,l,gameCharacter({body:v,outfit:creatorState.outfit},{gear:false}))).join('')}</div>`;
if(tab==='outfit')content=`<h3>Цвет одежды</h3><div class="hero-option-grid">${CHARACTER_OPTIONS.outfit.map(v=>option('outfit',v,OUTFIT_NAMES[v],`<span class="hero-color hero-color-${v}"></span>`)).join('')}</div><p class="hero-studio-hint">Праздничные наряды и подарки откроются в путешествии.</p>`;
$('#heroOptions').innerHTML=content;root.querySelectorAll('[data-hero-part]').forEach(b=>b.onclick=()=>{creatorState[b.dataset.heroPart]=b.dataset.heroPart==='backpack'?b.dataset.heroValue==='true':b.dataset.heroValue;refresh();options();root.querySelector(`[data-hero-part="${b.dataset.heroPart}"][data-hero-value="${b.dataset.heroValue}"]`)?.focus()})}
function refresh(){saveDraft();$('#heroModel').innerHTML=gameCharacter({...(creating?{}:existing),character:creatorState},{gear:false});$('#heroSummary').textContent=OUTFIT_NAMES[creatorState.outfit]+' комплект';const path=paths.find(p=>p.id===creatorState.path);$('#heroStats').innerHTML=path.stats.map((v,i)=>`<div class="hero-stat"><span>${['Любознательность','Смелость','Творчество'][i]}</span><span class="hero-stat-bar"><i style="width:${v}%"></i></span><span>${v}</span></div>`).join('');root.querySelectorAll('[data-hero-path]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.heroPath===creatorState.path)))}
root.querySelectorAll('[data-hero-tab]').forEach(b=>b.onclick=()=>{creatorState.tab=b.dataset.heroTab;saveDraft();options()});root.querySelectorAll('[data-hero-path]').forEach(b=>b.onclick=()=>{creatorState.path=b.dataset.heroPath;refresh()});$('#characterNick').oninput=e=>{creatorState.nick=e.target.value;$('#characterError').textContent='';saveDraft()};$('#heroRandom').onclick=()=>{for(const key of ['body','outfit'])creatorState[key]=CHARACTER_OPTIONS[key][Math.floor(Math.random()*CHARACTER_OPTIONS[key].length)];creatorState.path=paths[Math.floor(Math.random()*paths.length)].id;creatorState.nick=['Лесной Луч','Звонкий Ручей','Солнечный Тим','Искорка','Следопыт','Кедр','Лунный Лис'][Math.floor(Math.random()*7)];$('#characterNick').value=creatorState.nick;refresh();options()};
let saved=false;$('#characterForm').onsubmit=e=>{e.preventDefault();if(saved)return;const nick=$('#characterNick').value.trim(),code=creating?pendingJoin.code:existing.code;if(!/^[\p{L}\p{N}_ -]{2,20}$/u.test(nick)){$('#characterError').textContent='Выбери ник от 2 до 20 символов: буквы, цифры, пробел, _ или -.';$('#characterNick').focus();return}if(db.users.some(v=>v.code===code&&v.nick===nick&&(creating||v.id!==existing.id))){$('#characterError').textContent='Такой ник уже занят. Придумай другой или войди в своего персонажа.';$('#characterNick').focus();return}const character={...characterData(creatorState),path:creatorState.path,backpack:creatorState.backpack,companion:creatorState.companion};if(creating){const newUser={id:crypto.randomUUID(),nick,code,mode:pendingJoin.mode||'class',character,completed:[],attempts:[]};db.users.push(newUser);db.current=newUser.id}else{existing.nick=nick;existing.character=character}save();saved=true;$('#heroCreatedArt').innerHTML=gameCharacter(user(),{gear:false});$('#heroCreatedName').textContent=nick;$('#heroCreatedPath').textContent=paths.find(p=>p.id===character.path).name;pendingJoin=null;creatorState=null;sessionStorage.removeItem('ethnohod-pending-join');sessionStorage.removeItem('ethnohod-character-draft');$('#heroCreated').showModal();$('#heroContinue').focus()};const finish=()=>{location.hash=creating?'map':'profile'};$('#heroContinue').onclick=finish;$('#heroCreated').addEventListener('cancel',e=>{e.preventDefault();finish()});options();refresh();
}
